      "“让爸爸吃那碗有蛋的吧！”父亲说，“孔融七岁能让梨，你十岁啦，该让蛋啦！”“孔融是孔融，我是我，不让！”儿子态度坚决。",
      "待儿子吃完，父亲开始吃。当然父亲碗里藏了两个荷包蛋，儿子看得分明。“记住：想占便宜的人，往往占不到便宜！”父亲指着碗里的荷包蛋告诫儿子。儿子显出一脸的无奈。",
