      "小城里每一个庭院都栽了很多树。有按树、椰子树、橄榄树、凤凰树,还有别的许多亚热带树木。初夏,桉树叶子散发出来的香味,飘得满街满院都是。凤凰树开了花,开得那么热闹,小城好像笼罩在一片片红云中。",
