      "从前有一对农民夫妻,生下了一个大拇指那么一丁点大的小男孩,他们叫他“大拇指”。有一天,农民打算到树林里去砍柴,临行前自言自语:“我真希望有一个人能帮我把马车赶去,这样我就快多了。”“爸爸,”大拇指高声说,“车我一定赶来,你放心好啦,它会准时驶进树林里的。”农民笑起来,说:“怎么个赶法啊?你这个小不点,连拉马缰都够不着!”“没问题,爸,只要妈妈套好马,我就坐在马耳朵里,告诉它该怎么走。”爸爸只得答应:“好吧!咱们就挑战一次。”说完,他自己一人先去了。",
      "时间到了,妈妈套好马,把大拇指放进马耳朵里,这个小家伙果然吆喝着指挥起马来:“驾!驾!吁——吁——”马很听话,就像赶车的是位老把式。这时,迎面走来两个陌生人。“我的天!”其中一个说,“这是怎么回事?竟有这种怪事!车子在走,又听见马夫在吆喝,却看不见人!”“对,有问题!”另一个说,“咱们连续跟着车,看它停在什么地方。”马车驶进树林深处,正好在农民砍柴的地方停下来。",
