      "上初中时,我喜欢《格林童话》到了痴迷的地步。那时,父母工资微薄,除了勉强维持生活以外,根本没有剩余的钱去买一本既不能吃又不能穿的书。",
      "平时父母总是把钱放在写字台的抽屉里,而钥匙就放在写字台上。几经犹豫之后,我试着用钥匙打开了抽屉,从里面拿走了一张2元的纸币。第二天,我从书店里买回了那本梦寐以求的《格林童话》。",
      "几天过去了,风平浪静,父母似乎并没有发现我拿钱的事。不久,书店里进了一批新书,其中《绿野仙踪》是我盼望已久的一本童话故事。禁不住仙子的诱惑,我如法炮制。当我再一次打开写字台抽屉时,却发现里面多了一张纸条:峰儿,你是个好孩子,爸爸妈妈相信你会永远做一个好孩子。",
